import{_ as o,o as t,c as a,a0 as i}from"./chunks/framework.DW5bL-_G.js";const p=JSON.parse('{"title":"Changelog","description":"Release notes for ew-color-picker, including fixes, features and documentation updates.","frontmatter":{"title":"Changelog","description":"Release notes for ew-color-picker, including fixes, features and documentation updates."},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),n={name:"guide/changelog.md"};function r(d,e,c,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_2-0-3" tabindex="-1">2.0.3 <a class="header-anchor" href="#_2-0-3" aria-label="Permalink to &quot;2.0.3&quot;">​</a></h2><blockquote><p>This release has been published to npm and the docs site has been updated.</p></blockquote><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>New <code>@ew-color-picker/eyedropper</code> plugin: sample colors from anywhere on screen through the native EyeDropper API. It detects browser support, writes the result with <code>core.setColor()</code>, supports <code>showEyedropper</code> / <code>eyedropperText</code> / <code>onEyedropperPick</code>, and silently ignores <code>AbortError</code> when the user cancels</li><li>New <code>@ew-color-picker/copy-color</code> plugin: copy the current color to the clipboard with one click. The button is filled with the current color and uses contrast-aware icons, prefers the async Clipboard API with a <code>execCommand</code> fallback, shows a short built-in success toast, and supports <code>showCopyColor</code> / <code>copyColorText</code> / <code>copiedText</code> / <code>onCopyColor</code></li><li>The eyedropper and copy buttons now live in their own toolbar row above the color value input, instead of sharing the row with the Clear / Sure buttons</li></ul><h3 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed the InputNumber stepper arrows: they now carry the correct icon class and render at 10px, staying centered inside the button instead of overflowing and being clipped by the divider</li><li>Fixed RGB / HSL channel inputs resetting to <code>0</code> on the first stepper click; internal values are now synced with the current color so increment/decrement starts from the current channel value</li></ul><h2 id="_2-0-2" tabindex="-1">2.0.2 <a class="header-anchor" href="#_2-0-2" aria-label="Permalink to &quot;2.0.2&quot;">​</a></h2><h3 id="fixes-1" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-1" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Published package manifests now reference the matching release version (<code>^2.0.2</code>) for internal dependencies instead of the stale <code>^2.0.0</code> range. This prevents mixed installs where a 2.0.1 plugin resolved an older <code>@ew-color-picker/utils</code> that did not export <code>getPrefix</code></li></ul><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to &quot;2.0.1&quot;">​</a></h2><blockquote><p>These changes have been published to npm and are reflected in the docs site.</p></blockquote><h3 id="fixes-2" tabindex="-1">Fixes <a class="header-anchor" href="#fixes-2" aria-label="Permalink to &quot;Fixes&quot;">​</a></h3><ul><li>Fixed plugin switches being overridden: <code>ewColorPickerPanel: false</code> and <code>ewColorPickerColorMode: false</code> (or an object config) were replaced by defaults and did not take effect</li><li>Panel container now declares <code>box-sizing: content-box</code>, no longer relying on the host global <code>box-sizing</code> reset</li><li>Removed viewport media queries (<code>max-width: 768px</code>) that hard-coded panel, input and preset sizes; inner sizes are now driven solely by <code>--panel-width</code> / <code>--panel-height</code></li><li>Predefined swatches now use flex wrapping; removed the hard-coded &quot;10 per row&quot; rule that caused wrong wrapping when the swatch count or container width changed</li><li><code>use()</code> now deduplicates by <code>pluginName</code>, preventing duplicate registration under HMR, repeated imports or multiple entry points</li><li>Plugin constructor errors are now reported through <code>console.warn</code> with the plugin name and error details instead of being silently swallowed, making custom plugin debugging easier</li></ul><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>New <code>appendTo</code> option: mount the panel container into <code>document.body</code> or any container to avoid <code>overflow</code> clipping by dialogs, drawers and scroll containers. The panel then uses viewport-relative positioning, still honors <code>panelPlacement</code> with boundary flipping, and re-positions on scroll or resize</li><li>New <code>prefix</code> option: customize the prefix of every CSS class name (default <code>ew-</code>) to avoid style collisions when embedding the picker in another library. The SCSS build exposes a matching <code>$prefix</code> variable that must stay in sync with the JS option</li><li><code>ApplyOrder</code> changed from <code>const enum</code> to a regular enum, so it can be imported at runtime from <code>@ew-color-picker/utils</code> without hand-writing <code>&#39;pre&#39;</code> / <code>&#39;post&#39;</code> strings</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Corrected predefined swatch and number input class names to match the source</li><li>Removed the non-existent nested <code>ewColorPickerBox</code> config in favor of top-level options</li><li>Corrected the prerequisites of <code>autoPanelPosition</code></li><li>Added <code>appendTo</code> documentation (Chinese and English)</li><li>Added <code>prefix</code> documentation (Chinese and English) with a custom SCSS build example</li><li>Added <code>applyOrder</code> execution-order documentation and examples (Chinese and English)</li><li>The docs site now defaults to English; Chinese docs moved under <code>/zh/</code>, and the README defaults to English</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to &quot;2.0.0&quot;">​</a></h2><p>First stable release: core + plugin architecture, 14 packages (13 scoped packages plus the unscoped <code>ew-color-picker</code> entry package), bilingual docs site and live demo.</p>',20)])])}const g=o(n,[["render",r]]);export{p as __pageData,g as default};
